package com.shazwan.idash;
import android.app.*;import android.content.*;import android.os.*;import java.io.*;import java.nio.file.*;import java.util.*;
/** Positive reset on a disposable emulator; restores original preferences/files afterwards. */
public class SettingsResetChecks extends Instrumentation {
 LauncherActivity a;SharedPreferences prefs,fm;Map<String,?> before,fmBefore;int count;File cache,image;byte[] cacheBefore,imageBefore;boolean cacheCreated;
 void check(boolean ok,String why){if(!ok)throw new AssertionError(why);count++;}
 void ui(Runnable r){Throwable[] e={null};runOnMainSync(()->{try{r.run();}catch(Throwable t){e[0]=t;}});waitForIdleSync();if(e[0]!=null)throw new AssertionError(e[0]);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();int code=Activity.RESULT_CANCELED;try{
  prefs=getTargetContext().getSharedPreferences("idash",0);fm=getTargetContext().getSharedPreferences(DashFmController.PREFS,0);before=new HashMap<>(prefs.getAll());fmBefore=new HashMap<>(fm.getAll());cache=new File(getTargetContext().getFilesDir(),"jakim-SGR02.json");if(cache.exists())cacheBefore=Files.readAllBytes(cache.toPath());else{try(InputStream in=getTargetContext().getAssets().open("jakim/SGR02.json")){Files.copy(in,cache.toPath());}cacheCreated=true;cacheBefore=Files.readAllBytes(cache.toPath());}image=CustomWallpaper.file(getTargetContext());if(image.exists())imageBefore=Files.readAllBytes(image.toPath());
  prefs.edit().putString("favorite_Bluetooth","dev.idash.reset/.Marker").putBoolean("calendar",false).putInt("dock_size",1).putString("jakim_zone","SGR02").commit();fm.edit().putString("settings-reset-test","retained").commit();
  a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ui(()->new DashSettings(a).open("About"));ui(()->{a.settingsScreen.actions.reset();check(a.settingsScreen.dialog!=null,"positive reset requires explicit dialog");});ActivityMonitor monitor=addMonitor(LauncherActivity.class.getName(),null,false);ui(()->a.settingsScreen.dialog.getButton(AlertDialog.BUTTON_POSITIVE).performClick());Activity next=waitForMonitorWithTimeout(monitor,20000);removeMonitor(monitor);check(next instanceof LauncherActivity,"confirmed reset recreates launcher");a=(LauncherActivity)next;
  check(prefs.getBoolean("calendar",true)&&prefs.getInt("dock_size",0)==0,"confirmed reset restores widget/dock defaults");check(!"dev.idash.reset/.Marker".equals(prefs.getString("favorite_Bluetooth","")),"confirmed reset removes old app assignment");check(prefs.getString("jakim_zone","").isEmpty(),"reset zone requires fresh explicit choice");check("retained".equals(fm.getString("settings-reset-test","")),"FM preferences remain intact");check(Arrays.equals(cacheBefore,Files.readAllBytes(cache.toPath())),"official JAKIM cache retained byte-for-byte");if(imageBefore!=null)check(Arrays.equals(imageBefore,Files.readAllBytes(image.toPath())),"saved custom image retained byte-for-byte");
  result.putString("stream","PASS: "+count+" explicit Settings reset/retained-data checks\n");code=Activity.RESULT_OK;
 }catch(Throwable e){result.putString("stream","FAIL after "+count+": "+e+"\n");}finally{if(prefs!=null&&before!=null)AppearanceChecks.restore(prefs,before);if(fm!=null&&fmBefore!=null)AppearanceChecks.restore(fm,fmBefore);if(cacheCreated&&cache!=null)cache.delete();if(a!=null)ui(()->a.finish());}finish(code,result);}
}
